// One schema, three consumers: editor palette, renderer, GraphQL types.
// Adding a block type here makes TypeScript demand a renderer branch for it.
export const blockSchema = z.discriminatedUnion('type', [
  z.object({ type: z.literal('h2'), text: z.string().min(1) }),
  z.object({ type: z.literal('h3'), text: z.string().min(1) }),
  z.object({ type: z.literal('p'),  text: z.string().min(1) }),
  z.object({ type: z.literal('ul'), items: z.array(z.string()).min(1) }),
  z.object({ type: z.literal('code'), lang: z.string(), code: z.string() }),
  z.object({
    type: z.literal('image'),
    src: z.string(),
    // Required, not optional — an empty alt is a decision, not a default.
    alt: z.string(),
    caption: z.string().optional(),
  }),
  z.object({ type: z.literal('hr') }),
]);

export type Block = z.infer<typeof blockSchema>;
